import yaml,glob,collections
rows={}
for f in glob.glob('*.yaml'):
    d=yaml.safe_load(open(f))
    rows[d['id']]=d
print('rows:',len(rows))
print(collections.Counter(r['status'] for r in rows.values()))
# parent/child mismatches
kids=collections.defaultdict(list)
for r in rows.values():
    p=r.get('metadata',{}).get('parent')
    if p: kids[p].append(r)
bad=[]
for p,cs in kids.items():
    par=rows.get(p)
    if not par: print('MISSING PARENT', p); continue
    if par['status'] not in ('done','rejected') and all(c['status'] in ('done','rejected') for c in cs):
        bad.append((p,par['status'],[ (c['id'],c['status']) for c in cs]))
print('\nparent open / all children done:')
for b in bad: print(' ',b)
EOF

